// wf.fx.refresh > "Parse rates"
// ECB daily XML (gesmes envelope): one Cube with time="YYYY-MM-DD" holding
// Cube currency="USD" rate="1.1225" elements; 1 EUR = rate units of the currency.
// Reuse condition of the ECB (D-057): the ECB is cited as the source on every row.
const start = $('Start job').first().json;
const xml = String($input.first().json.data || '');
const t = /<Cube\s+time=['"](\d{4}-\d{2}-\d{2})['"]/.exec(xml);
if (!t) throw new Error('ECB answer has no dated Cube element');
const rates = [];
const re = /<Cube\s+currency=['"]([A-Z]{3})['"]\s+rate=['"]([0-9.]+)['"]\s*\/>/g;
let m;
while ((m = re.exec(xml))) {
  rates.push({ base: 'EUR', quote: m[1], rate: m[2], as_of: t[1],
    source: 'European Central Bank, euro foreign exchange reference rates (https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml)' });
}
if (!rates.length) throw new Error('ECB answer has no rates');
return [{ json: { job_id: start.job_id, as_of: t[1], published: rates.length, params: [JSON.stringify({ rates })] } }];

// wf.fx.refresh > "Summarize"
const p = $('Parse rates').first().json;
const stored = $input.first().json.stored;
return [{ json: { job_id: p.job_id, status: 'succeeded', error: null,
  output: { as_of: p.as_of, published: p.published, stored, note: 'rates for currencies not in app.currencies are skipped' } } }];

// Worker workflows (wf.kb.ingest, wf.eval.retrieval) > "Job failed"
// Error output of any step after "Start job": the job ends as failed with the
// (redacted) error text, so it never stays "running" after a handled failure.
// Text of the error carried by an item on a node's error output.
// n8n puts either a string or an object {message, description, ...} in json.error.
function errorText(json) {
  const e = json && (json.error !== undefined ? json.error : json);
  if (e == null) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description, e.cause && e.cause.message].filter((x) => typeof x === 'string' && x);
  return parts.length ? parts.join(' | ') : JSON.stringify(e);
}
// Postgres error details echo the offending value, e.g. Key (email)=(a@b.c).
// Values are removed before anything is logged.
function redactPg(msg) {
  return String(msg || '').replace(/\)=\([^)]*\)/g, ')=(redacted)');
}
if (typeof module !== 'undefined') module.exports = { errorText, redactPg };

const start = $('Start job').first().json;
const msg = redactPg(errorText($input.first().json)).slice(0, 500) || 'worker step failed without a message';
return [{ json: { job_id: start.job_id, status: 'failed', error: msg, output: { failed_step: true } } }];
